// 실제 배포 환경에서는 Claude 전용 window.storage 대신 브라우저 localStorage를 사용합니다.
async function storeGet(key) {
  try {
    const raw = localStorage.getItem(key);
    return raw ? JSON.parse(raw) : null;
  } catch {
    return null;
  }
}
async function storeSet(key, value) {
  try {
    localStorage.setItem(key, JSON.stringify(value));
    return true;
  } catch {
    return false;
  }
}
const uid = () => Math.random().toString(36).slice(2, 10);

// 사진을 적당한 크기로 줄여서 base64로 반환 (localStorage 용량 절약)
function resizeImageFile(file, maxWidth = 720, quality = 0.6) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onerror = () => reject(new Error("파일을 읽을 수 없어요."));
    reader.onload = () => {
      const img = new Image();
      img.onload = () => {
        const scale = Math.min(1, maxWidth / img.width);
        const w = Math.round(img.width * scale);
        const h = Math.round(img.height * scale);
        const canvas = document.createElement("canvas");
        canvas.width = w;
        canvas.height = h;
        const ctx = canvas.getContext("2d");
        ctx.drawImage(img, 0, 0, w, h);
        resolve(canvas.toDataURL("image/jpeg", quality));
      };
      img.onerror = () => reject(new Error("이미지를 불러올 수 없어요."));
      img.src = reader.result;
    };
    reader.readAsDataURL(file);
  });
}
const won = (n) => Math.round(n).toLocaleString("ko-KR") + "원";

// 백엔드(서버) 주소와 관리자 키. Render 등에 배포한 뒤 이 두 값을 채워 넣으면
// 예약·사진 데이터가 모든 기기에서 함께 보이고, 사장님 이메일로 자동 알림도 갑니다. (README 참고)
const BACKEND_URL = "https://gilgal-backend.onrender.com";
const BACKEND_ADMIN_KEY = "gilgal2026key"; // 백엔드 .env의 ADMIN_KEY와 반드시 같은 값으로 넣어주세요.

async function apiPost(path, body) {
  if (!BACKEND_URL) return null;
  try {
    const res = await fetch(`${BACKEND_URL}${path}`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(body),
    });
    return await res.json();
  } catch (e) {
    console.warn("백엔드 요청 실패:", path, e);
    return null;
  }
}
async function apiGet(path) {
  if (!BACKEND_URL) return null;
  try {
    const res = await fetch(`${BACKEND_URL}${path}`);
    return await res.json();
  } catch (e) {
    console.warn("백엔드 요청 실패:", path, e);
    return null;
  }
}
async function apiPatch(path, body) {
  if (!BACKEND_URL) return null;
  try {
    const res = await fetch(`${BACKEND_URL}${path}`, {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(body),
    });
    return await res.json();
  } catch (e) {
    console.warn("백엔드 요청 실패:", path, e);
    return null;
  }
}
async function apiDelete(path) {
  if (!BACKEND_URL) return null;
  try {
    const res = await fetch(`${BACKEND_URL}${path}`, { method: "DELETE" });
    return await res.json();
  } catch (e) {
    console.warn("백엔드 요청 실패:", path, e);
    return null;
  }
}

async function notifyBackend(reservation) {
  return apiPost("/api/reservations", reservation);
}
async function fetchAdminReservations() {
  const data = await apiGet(`/api/reservations?key=${encodeURIComponent(BACKEND_ADMIN_KEY)}`);
  return data && data.ok ? data.reservations : null;
}
async function patchReservation(id, patch) {
  return apiPatch(`/api/reservations/${id}?key=${encodeURIComponent(BACKEND_ADMIN_KEY)}`, patch);
}
async function deleteReservationBackend(id) {
  return apiDelete(`/api/reservations/${id}?key=${encodeURIComponent(BACKEND_ADMIN_KEY)}`);
}
async function fetchGalleryBackend() {
  const data = await apiGet("/api/gallery");
  return data && data.ok ? data.posts : null;
}
async function postGalleryBackend(post) {
  return apiPost(`/api/gallery?key=${encodeURIComponent(BACKEND_ADMIN_KEY)}`, post);
}
async function deleteGalleryBackend(id) {
  return apiDelete(`/api/gallery/${id}?key=${encodeURIComponent(BACKEND_ADMIN_KEY)}`);
}

function dateRange(checkIn, checkOut) {
  const out = [];
  let d = new Date(checkIn);
  const end = new Date(checkOut);
  while (d < end) { out.push(new Date(d)); d.setDate(d.getDate() + 1); }
  return out;
}
function isWeekendNight(d) {
  const day = d.getDay(); // 0=일 5=금 6=토
  const iso = d.toISOString().slice(0, 10);
  return day === 5 || day === 6 || day === 0 || HOLIDAYS_2026.has(iso);
}

function calcTotal(checkIn, checkOut, wantsFirewood) {
  if (!checkIn || !checkOut) return { nights: 0, total: 0 };
  const nights = dateRange(checkIn, checkOut);
  if (nights.length === 0) return { nights: 0, total: 0 };
  let total = 0;
  nights.forEach((d) => { total += isWeekendNight(d) ? BASE_WEEKEND : BASE_WEEKDAY; });
  if (wantsFirewood) total += FIREWOOD_FEE;
  return { nights: nights.length, total };
}

function monthKey(dateStr) { return (dateStr || "").slice(0, 7); }

function last6Months() {
  const arr = [];
  const now = new Date();
  for (let i = 5; i >= 0; i--) {
    const d = new Date(now.getFullYear(), now.getMonth() - i, 1);
    arr.push(`${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}`);
  }
  return arr;
}

// 지금까지 기록된 모든 데이터(예약·공과금·비품구매·유지보수)를 월별로 합산
function computeAllMonthlyTotals(reservations, inventory, utilityBills, maintenance) {
  const monthSet = new Set();
  reservations.forEach((r) => { if (r.status !== "취소") monthSet.add(monthKey(r.checkIn)); });
  utilityBills.forEach((u) => monthSet.add(u.month));
  inventory.forEach((i) => i.purchaseHistory.forEach((p) => monthSet.add(monthKey(p.date))));
  maintenance.forEach((m) => monthSet.add(monthKey(m.date)));
  monthSet.delete("");

  const months = [...monthSet].sort();
  return months.map((m) => {
    const revenue = reservations.filter((r) => r.status !== "취소" && monthKey(r.checkIn) === m).reduce((s, r) => s + r.total, 0);
    const utilityCost = utilityBills.filter((u) => u.month === m).reduce((s, u) => s + u.amount, 0);
    const purchaseCost = inventory.reduce((s, item) => s + item.purchaseHistory.filter((p) => monthKey(p.date) === m).reduce((ss, p) => ss + p.cost, 0), 0);
    const maintCost = maintenance.filter((e) => monthKey(e.date) === m).reduce((s, e) => s + e.amount, 0);
    const expense = utilityCost + purchaseCost + maintCost;
    return { month: m, revenue, expense, profit: revenue - expense };
  });
}

function groupByYear(monthlyTotals) {
  const map = new Map();
  monthlyTotals.forEach((row) => {
    const year = row.month.slice(0, 4);
    if (!map.has(year)) map.set(year, { year, revenue: 0, expense: 0, profit: 0 });
    const y = map.get(year);
    y.revenue += row.revenue;
    y.expense += row.expense;
    y.profit += row.profit;
  });
  return [...map.values()].sort((a, b) => a.year.localeCompare(b.year));
}

/* ---------------------------- 시그니처: 스톤 서클 ---------------------------- */

function StoneCircle({ size = 40, tone = "#B5573A" }) {
  const stones = 8;
  const items = Array.from({ length: stones });
  const r = size * 0.36;
  const c = size / 2;
  return (
    <svg width={size} height={size} viewBox={`0 0 ${size} ${size}`}>
      {items.map((_, i) => {
        const angle = (i / stones) * Math.PI * 2 - Math.PI / 2;
        const x = c + r * Math.cos(angle);
        const y = c + r * Math.sin(angle);
        const rw = size * 0.11, rh = size * 0.08;
        return <ellipse key={i} cx={x} cy={y} rx={rw} ry={rh} fill={i === 0 ? tone : "currentColor"} transform={`rotate(${(angle * 180) / Math.PI + 90} ${x} ${y})`} />;
      })}
      <circle cx={c} cy={c} r={size * 0.06} fill="currentColor" opacity="0.4" />
    </svg>
  );
}

